//! Variants of the engine bench's data (docs/benchmarks.md, "Big dimension and skewed data").
//!
//! The standard bench (`engine_bench.rs`) has small dimensions and uniform keys, which can hide
//! what a real model costs. Two variants, generated by the same `gen` step and built by
//! `bicraft run` like the standard one:
//!
//! - **`bigdim`**: the standard star schema plus a `Client` dimension of millions of rows
//!   (default: one customer for five sales lines) with several attributes (`Client` unique text,
//!   `Segment`, `Ville`, `Pays` (a function of `Ville`), `TrancheAge`, `Fidelite`), related to
//!   `Ventes[ClientKey]`. Its queries filter and group by those attributes.
//! - **`skew`**: Zipf-like keys (100,000 products and the stores with weights `1/k`, customers
//!   `1/(k+100)`: a few huge groups, many tiny ones), sales written in date order with mostly one
//!   unit and no discount (long runs once the engine sorts a segment), an order number shared by
//!   1–5 lines (`Ventes[NumCommande]`, high-cardinality text in the fact), and 1 % anonymous
//!   sales (blank `ClientKey`: the dimension's blank row).
//!
//! The weights are integers (no floating-point power), so a seed gives the same bytes on every
//! platform. Each variant has its own queries file (`xtask/engine-bench/queries-<variant>.json`),
//! which Desktop's side (`desktop.ps1 -Queries`) reads as it reads the standard one.

use std::fmt::Write as _;
use std::path::Path;
use std::time::Instant;

use serde_json::{Value, json};

use crate::engine_bench::{
    CATEGORIES, MEASURES, REGIONS, STORES, SUBCATEGORIES, calendar_days, cents, csv_file, m_csv, price_cents,
    report_commands, sale, splitmix, write, ymd,
};

const QUERIES_BIGDIM: &str = include_str!("../engine-bench/queries-bigdim.json");
const QUERIES_SKEW: &str = include_str!("../engine-bench/queries-skew.json");

/// Products of the skewed variant.
pub const SKEW_PRODUCTS: u64 = 100_000;
/// Cities of the big dimension, and the countries they belong to.
pub const CITIES: u64 = 2_000;
pub const COUNTRIES: u64 = 40;
pub const SEGMENTS: u64 = 6;
pub const AGE_BANDS: u64 = 7;

/// Which data the bench generates.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Variant {
    Standard,
    BigDim,
    Skew,
}

impl Variant {
    pub fn parse(s: &str) -> Result<Variant, String> {
        match s {
            "standard" => Ok(Variant::Standard),
            "bigdim" => Ok(Variant::BigDim),
            "skew" => Ok(Variant::Skew),
            _ => Err(format!("unknown variant `{s}` (standard, bigdim, skew)")),
        }
    }

    pub fn name(self) -> &'static str {
        match self {
            Variant::Standard => "standard",
            Variant::BigDim => "bigdim",
            Variant::Skew => "skew",
        }
    }

    /// The variant's queries (the standard ones are `queries.json`).
    pub fn queries_text(self) -> Option<&'static str> {
        match self {
            Variant::Standard => None,
            Variant::BigDim => Some(QUERIES_BIGDIM),
            Variant::Skew => Some(QUERIES_SKEW),
        }
    }

    /// Customers by default for `rows` sales lines.
    pub fn default_customers(self, rows: u64) -> u64 {
        match self {
            Variant::Standard | Variant::Skew => crate::engine_bench::default_customers(rows),
            Variant::BigDim => (rows / 5).max(1_000),
        }
    }

    /// The fact's columns (for the per-column load profile).
    pub fn fact_columns(self) -> &'static [&'static str] {
        match self {
            Variant::Standard | Variant::BigDim => &[
                "Date",
                "ProduitKey",
                "MagasinKey",
                "ClientKey",
                "Quantite",
                "Montant",
            ],
            Variant::Skew => &[
                "Date",
                "ProduitKey",
                "MagasinKey",
                "ClientKey",
                "NumCommande",
                "Quantite",
                "Montant",
            ],
        }
    }
}

/// Parses a queries document (`{"queries": [...]}`).
pub fn parse_queries(text: &str, what: &str) -> Result<Vec<Value>, String> {
    let v: Value = serde_json::from_str(text).map_err(|e| format!("{what}: {e}"))?;
    v.get("queries")
        .and_then(Value::as_array)
        .cloned()
        .ok_or_else(|| format!("{what}: no `queries` array"))
}

// ---------------------------------------------------------------------------------------------
// Skewed draws
// ---------------------------------------------------------------------------------------------

/// Cumulative integer weights `W / (k + offset)` for `k = 1..=n`: a Zipf-like law (exponent 1)
/// without floating point, so every platform draws the same keys.
pub struct Zipf {
    cum: Vec<u64>,
}

impl Zipf {
    pub fn new(n: u64, offset: u64) -> Zipf {
        const W: u64 = 1 << 40;
        let mut cum = Vec::with_capacity(usize::try_from(n).unwrap_or(0));
        let mut total = 0u64;
        for k in 1..=n {
            total = total.saturating_add(W / (k + offset).max(1));
            cum.push(total);
        }
        Zipf { cum }
    }

    /// The key (1-based) that the random word `r` draws.
    pub fn draw(&self, r: u64) -> u64 {
        let total = self.cum.last().copied().unwrap_or(0);
        if total == 0 {
            return 1;
        }
        let x = r % total;
        // first cumulative weight above x
        self.cum.partition_point(|&c| c <= x) as u64 + 1
    }
}

