/// The customer dimension (both variants): `ClientKey,Client,Segment,Ville,Pays,TrancheAge,Fidelite`.
fn client_csv(out: &Path, customers: u64) -> Result<(), String> {
    csv_file(
        &out.join("Client.csv"),
        "ClientKey,Client,Segment,Ville,Pays,TrancheAge,Fidelite",
        customers,
        |k, s| {
            let r = splitmix(k ^ 0x00C1_1E17);
            let segment = 1 + r % SEGMENTS;
            let city = 1 + (r >> 8) % CITIES;
            let country = 1 + (city - 1) % COUNTRIES;
            let age = 1 + (r >> 24) % AGE_BANDS;
            let loyal = if (r >> 40) % 10 < 3 { "Oui" } else { "Non" };
            let _ = write!(
                s,
                "{k},C{k:07},Segment{segment},Ville{city:04},Pays{country:02},A{age},{loyal}"
            );
        },
    )
}

fn product_csv(out: &Path, products: u64) -> Result<(), String> {
    csv_file(
        &out.join("Produit.csv"),
        "ProduitKey,Produit,Categorie,SousCategorie,PrixCatalogue",
        products,
        |k, s| {
            let sub = 1 + splitmix(k ^ 0xAB) % SUBCATEGORIES;
            let cat = 1 + (sub - 1) % CATEGORIES;
            let name = if products > 9_999 {
                format!("P{k:06}")
            } else {
                format!("P{k:04}")
            };
            let _ = write!(s, "{k},{name},Cat{cat:02},Sous{sub:02},{}", cents(price_cents(k)));
        },
    )
}

fn store_csv(out: &Path) -> Result<(), String> {
    csv_file(
        &out.join("Magasin.csv"),
        "MagasinKey,Magasin,Region",
        STORES,
        |k, s| {
            let region = 1 + splitmix(k ^ 0x5EED) % REGIONS;
            let _ = write!(s, "{k},M{k:03},Region{region}");
        },
    )
}

fn calendar_csv(out: &Path) -> Result<(), String> {
    csv_file(
        &out.join("Calendrier.csv"),
        "Date,Annee,MoisNum,AnneeMois",
        calendar_days() as u64,
        |k, s| {
            let (y, m, d) = ymd(k as i64 - 1);
            let _ = write!(s, "{y:04}-{m:02}-{d:02},{y},{m},{}", y * 100 + m);
        },
    )
}

/// One line of the skewed fact, for row `k` (1-based) of `rows`, in date order.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct SkewLine {
    pub day: u64,
    pub product: u64,
    pub store: u64,
    /// `None`: an anonymous sale (blank key).
    pub customer: Option<u64>,
    pub order: u64,
    pub qty: u64,
    pub cents: u64,
}

/// Lines in order: an order holds 1–5 consecutive lines (one customer, one store, one day).
pub struct SkewGen {
    rows: u64,
    days: u64,
    products: Zipf,
    stores: Zipf,
    customers: Zipf,
    order: u64,
    left: u64,
    store: u64,
    customer: Option<u64>,
}

impl SkewGen {
    pub fn new(rows: u64, customers: u64) -> SkewGen {
        SkewGen {
            rows,
            days: calendar_days() as u64,
            products: Zipf::new(SKEW_PRODUCTS, 0),
            stores: Zipf::new(STORES, 0),
            customers: Zipf::new(customers, 100),
            order: 0,
            left: 0,
            store: 1,
            customer: None,
        }
    }

    pub fn line(&mut self, k: u64) -> SkewLine {
        let r = splitmix(k ^ 0x5EE0);
        let r2 = splitmix(r);
        if self.left == 0 {
            let o = splitmix(r2 ^ 0x0DE5);
            self.order += 1;
            self.left = 1 + o % 5;
            self.store = self.stores.draw(splitmix(o));
            self.customer = if (o >> 32).is_multiple_of(100) {
                None
            } else {
                Some(self.customers.draw(splitmix(o ^ 0xC0)))
            };
        }
        self.left -= 1;
        // in date order: the day grows with the row
        let day = ((k - 1).saturating_mul(self.days) / self.rows.max(1)).min(self.days - 1);
        let product = self.products.draw(r);
        // mostly one unit, sometimes up to 10
        let qty = if (r2 >> 8) % 10 < 7 { 1 } else { 2 + (r2 >> 16) % 9 };
        // no discount on 60 % of the lines, else 5..30 %
        let discount = if (r2 >> 24) % 10 < 6 {
            0
        } else {
            5 + (r2 >> 32) % 26
        };
        let cents = qty * price_cents(product) * (100 - discount) / 100;
        SkewLine {
            day,
            product,
            store: self.store,
            customer: self.customer,
            order: self.order,
            qty,
            cents,
        }
    }
}

/// `gen --variant bigdim|skew`: the CSV files, `build.json` and `meta.json`.
pub fn generate(out: &Path, variant: Variant, rows: u64, customers: u64, parts: u64) -> Result<(), String> {
    let parts = parts.clamp(1, 64);
    std::fs::create_dir_all(out).map_err(|e| format!("{}: {e}", out.display()))?;
    let out = crate::engine_bench::plain_dir(out)?;
    let t0 = Instant::now();
    let days = calendar_days() as u64;
    let products = match variant {
        Variant::Skew => SKEW_PRODUCTS,
        _ => crate::engine_bench::PRODUCTS,
    };
    product_csv(&out, products)?;
    store_csv(&out)?;
    calendar_csv(&out)?;
    client_csv(&out, customers)?;
    match variant {
        Variant::Standard => return Err("the standard data is `gen` without --variant".into()),
        Variant::BigDim => fact_parts(
            &out,
            "Date,ProduitKey,MagasinKey,ClientKey,Quantite,Montant",
            rows,
            parts,
            |k, s| {
                let (day, p, st, c, q, a) = sale(k, customers, days);
                let (y, m, d) = ymd(day as i64);
                let _ = write!(s, "{y:04}-{m:02}-{d:02},{p},{st},{c},{q},{}", cents(a));
            },
        )?,
        Variant::Skew => {
            let mut g = SkewGen::new(rows, customers);
            fact_parts(
                &out,
                "Date,ProduitKey,MagasinKey,ClientKey,NumCommande,Quantite,Montant",
                rows,
                parts,
                |k, s| {
                    let l = g.line(k);
                    let (y, m, d) = ymd(l.day as i64);
                    let c = l.customer.map(|c| c.to_string()).unwrap_or_default();
                    let _ = write!(
                        s,
                        "{y:04}-{m:02}-{d:02},{},{},{c},CMD{:08},{},{}",
                        l.product,
                        l.store,
                        l.order,
                        l.qty,
                        cents(l.cents)
                    );
                },
            )?;
        }
    }
    let pbix = out.join("bench.pbix");
    write(
        &out.join("build.json"),
        &serde_json::to_string_pretty(&build_commands_parts(&out, &pbix, variant, parts))
            .map_err(|e| e.to_string())?,
    )?;
    let meta = json!({"variant": variant.name(), "rows": rows, "customers": customers, "fact_parts": parts,
        "products": products, "stores": STORES, "days": days,
        "generated_s": t0.elapsed().as_secs_f64()});
    write(
        &out.join("meta.json"),
        &serde_json::to_string_pretty(&meta).map_err(|e| e.to_string())?,
    )?;
    eprintln!(
        "{} {rows} rows, {customers} customers -> {} ({:.1} s); next: bicraft run --file {}",
        variant.name(),
        out.display(),
        t0.elapsed().as_secs_f64(),
        out.join("build.json").display()
    );
    Ok(())
}

/// Most sales lines per fact file: bicraft's M reads files of at most 256 MB.
pub const ROWS_PER_PART: u64 = 4_000_000;

/// Fact files by default for `rows` lines.
pub fn default_parts(rows: u64) -> u64 {
    rows.div_ceil(ROWS_PER_PART).max(1)
}

/// The name of fact file `i` (0-based): `Ventes.csv`, then `Ventes_2.csv`, …
pub fn part_name(i: u64) -> String {
    if i == 0 {
        "Ventes.csv".into()
    } else {
        format!("Ventes_{}.csv", i + 1)
    }
}

/// The sales lines `1..=rows` in `parts` files of consecutive lines (one partition each).
fn fact_parts(
    out: &Path,
    header: &str,
    rows: u64,
    parts: u64,
    mut line: impl FnMut(u64, &mut String),
) -> Result<(), String> {
    let per = rows.div_ceil(parts.max(1)).max(1);
    for i in 0..parts.max(1) {
        let lo = i.saturating_mul(per);
        let n = rows.saturating_sub(lo).min(per);
        csv_file(&out.join(part_name(i)), header, n, |k, s| line(lo + k, s))?;
    }
    Ok(())
}

type Cols = &'static [(&'static str, &'static str)];

const PRODUIT: Cols = &[
    ("ProduitKey", "Int64.Type"),
    ("Produit", "type text"),
    ("Categorie", "type text"),
    ("SousCategorie", "type text"),
    ("PrixCatalogue", "Currency.Type"),
];
const MAGASIN: Cols = &[
    ("MagasinKey", "Int64.Type"),
    ("Magasin", "type text"),
    ("Region", "type text"),
];
const CALENDRIER: Cols = &[
    ("Date", "type date"),
    ("Annee", "Int64.Type"),
    ("MoisNum", "Int64.Type"),
    ("AnneeMois", "Int64.Type"),
];
const CLIENT: Cols = &[
    ("ClientKey", "Int64.Type"),
    ("Client", "type text"),
    ("Segment", "type text"),
    ("Ville", "type text"),
    ("Pays", "type text"),
    ("TrancheAge", "type text"),
    ("Fidelite", "type text"),
];
const VENTES: Cols = &[
    ("Date", "type date"),
    ("ProduitKey", "Int64.Type"),
    ("MagasinKey", "Int64.Type"),
    ("ClientKey", "Int64.Type"),
    ("Quantite", "Int64.Type"),
    ("Montant", "Currency.Type"),
];
const VENTES_SKEW: Cols = &[
    ("Date", "type date"),
    ("ProduitKey", "Int64.Type"),
    ("MagasinKey", "Int64.Type"),
    ("ClientKey", "Int64.Type"),
    ("NumCommande", "type text"),
    ("Quantite", "Int64.Type"),
    ("Montant", "Currency.Type"),
];

/// The `bicraft run --file` commands that build `pbix` from the CSV files in `dir`: the
/// standard model (tables, relationships, measures, bench report) or a variant's (no report:
/// the bench report's pages are the standard queries).
pub fn build_commands(dir: &Path, pbix: &Path, variant: Variant) -> Value {
    build_commands_parts(dir, pbix, variant, 1)
}

/// [`build_commands`] with the fact in `parts` files, one partition each.
pub fn build_commands_parts(dir: &Path, pbix: &Path, variant: Variant, parts: u64) -> Value {
    let root = dir.display().to_string();
    let mut tables: Vec<(&str, Cols)> = vec![
        ("Produit", PRODUIT),
        ("Magasin", MAGASIN),
        ("Calendrier", CALENDRIER),
    ];
    match variant {
        Variant::Standard => tables.push(("Ventes", VENTES)),
        Variant::BigDim => tables.extend([("Client", CLIENT), ("Ventes", VENTES)]),
        Variant::Skew => tables.extend([("Client", CLIENT), ("Ventes", VENTES_SKEW)]),
    }
    let mut c = vec![json!({"command": "model.new", "params": {"name": "Bench", "culture": "en-US"}})];
    for (name, types) in tables {
        let m = m_csv(&dir.join(format!("{name}.csv")), types);
        c.push(json!({"command": "table.import", "params": {"name": name, "m": m, "data_root": root}}));
        if name == "Ventes" {
            for i in 1..parts {
                let m = m_csv(&dir.join(part_name(i)), types);
                c.push(json!({"command": "partition.add", "params": {"table": name, "expression": m}}));
            }
        }
    }
    c.push(json!({"command": "table.set", "params": {"name": "Calendrier", "data_category": "Time", "key_column": "Date"}}));
    let mut rels = vec![
        ("Ventes[Date]", "Calendrier[Date]"),
        ("Ventes[ProduitKey]", "Produit[ProduitKey]"),
        ("Ventes[MagasinKey]", "Magasin[MagasinKey]"),
    ];
    if variant != Variant::Standard {
        rels.push(("Ventes[ClientKey]", "Client[ClientKey]"));
    }
    for (from, to) in rels {
        c.push(json!({"command": "relationship.add", "params": {"from": from, "to": to}}));
    }
    let mut measures: Vec<(&str, &str, &str)> = MEASURES.to_vec();
    if variant == Variant::Skew {
        measures.push(("Nb commandes", "DISTINCTCOUNT(Ventes[NumCommande])", "#,0"));
    }
    for (name, dax, fmt) in measures {
        c.push(json!({"command": "measure.add", "params": {"table": "Ventes", "name": name, "expression": dax, "format_string": fmt}}));
    }
    c.push(json!({"command": "report.new", "params": {}}));
    if variant == Variant::Standard {
        c.extend(report_commands());
    }
    c.push(json!({"command": "file.save_as", "params": {"path": pbix.display().to_string(), "overwrite": true, "data_root": root}}));
    Value::Array(c)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn variant_queries_parse_with_unique_ids() {
        for v in [Variant::BigDim, Variant::Skew] {
            let qs = parse_queries(v.queries_text().unwrap(), v.name()).unwrap();
            assert!(qs.len() >= 12, "{}", v.name());
            let mut ids: Vec<&str> = qs.iter().map(|q| q["id"].as_str().unwrap()).collect();
            ids.sort_unstable();
            ids.dedup();
            assert_eq!(ids.len(), qs.len());
            assert!(qs.iter().all(|q| q["dax"].as_str().unwrap().contains("EVALUATE")));
        }
    }

    #[test]
    fn zipf_is_skewed_and_in_range() {
        let z = Zipf::new(1_000, 0);
        let mut counts = vec![0u32; 1_001];
        for k in 0..200_000u64 {
            let x = z.draw(splitmix(k));
            assert!((1..=1_000).contains(&x));
            counts[x as usize] += 1;
        }
        // weight 1/k: the first key about twice the second, far above the last
        assert!(counts[1] > counts[2] * 3 / 2 && counts[2] > counts[4]);
        assert!(counts[1] > 50 * counts[1_000].max(1));
        assert_eq!(Zipf::new(0, 0).draw(7), 1);
    }

    #[test]
    fn skewed_lines_are_in_date_order_with_orders_of_one_to_five_lines() {
        let mut g = SkewGen::new(50_000, 5_000);
        let mut last_day = 0;
        let mut last_order = 0;
        let mut lines_of_order = 0;
        let mut anonymous = 0;
        for k in 1..=50_000 {
            let l = g.line(k);
            assert!(l.day >= last_day && l.day < 1826);
            assert!((1..=SKEW_PRODUCTS).contains(&l.product) && (1..=STORES).contains(&l.store));
            assert!(l.customer.is_none_or(|c| (1..=5_000).contains(&c)));
            if l.order == last_order {
                lines_of_order += 1;
            } else {
                assert_eq!(l.order, last_order + 1);
                lines_of_order = 1;
            }
            assert!(lines_of_order <= 5);
            anonymous += u32::from(l.customer.is_none());
            last_day = l.day;
            last_order = l.order;
        }
        assert!(anonymous > 0);
        // deterministic
        let mut a = SkewGen::new(1_000, 100);
        let mut b = SkewGen::new(1_000, 100);
        assert!((1..=1_000).all(|k| a.line(k) == b.line(k)));
    }

    #[test]
    fn variant_fact_is_split_in_partitions() {
        let dir = std::env::temp_dir().join(format!("bicraft-variant-parts-{}", std::process::id()));
        generate(&dir, Variant::Skew, 1_001, 100, 3).unwrap();
        let lines: Vec<usize> = (0..3)
            .map(|i| {
                std::fs::read_to_string(dir.join(part_name(i)))
                    .unwrap()
                    .lines()
                    .count()
                    - 1
            })
            .collect();
        assert_eq!(lines, [334, 334, 333]);
        let build = std::fs::read_to_string(dir.join("build.json")).unwrap();
        assert_eq!(build.matches("partition.add").count(), 2);
        assert!(build.contains("Ventes_3.csv"));
        // the order numbers continue from one file to the next
        let first_of_2 = std::fs::read_to_string(dir.join(part_name(1))).unwrap();
        let last_of_1 = std::fs::read_to_string(dir.join(part_name(0))).unwrap();
        let order = |l: &str| l.split(',').nth(4).unwrap().to_string();
        assert!(order(first_of_2.lines().nth(1).unwrap()) >= order(last_of_1.lines().last().unwrap()));
        let _ = std::fs::remove_dir_all(&dir);
        assert_eq!(default_parts(10_000_000), 3);
        assert_eq!(default_parts(10_000), 1);
    }

    #[test]
    fn variant_builds_relate_the_customer_dimension() {
        for v in [Variant::BigDim, Variant::Skew] {
            let c = build_commands(Path::new("C:/x"), Path::new("C:/x/bench.pbix"), v);
            let a = c.as_array().unwrap();
            assert!(
                a.iter()
                    .any(|x| x["command"] == "relationship.add" && x["params"]["to"] == "Client[ClientKey]")
            );
            assert_eq!(a.last().unwrap()["command"], "file.save_as");
        }
        let skew = build_commands(Path::new("C:/x"), Path::new("C:/x/b.pbix"), Variant::Skew);
        assert!(skew.to_string().contains("Nb commandes"));
    }
}
